const calendarStyle=document.createElement('link');calendarStyle.rel='stylesheet';calendarStyle.href='calendar.css';document.head.appendChild(calendarStyle);
const profileNav=document.querySelector('[data-view="profile"]'),calendarNav=document.createElement('button');calendarNav.type='button';calendarNav.dataset.view='calendar';calendarNav.innerHTML='Calendar <span id="calendarCount"></span>';profileNav.before(calendarNav);
const profileView=document.getElementById('profileView'),calendarView=document.createElement('section');calendarView.className='dashboard-view';calendarView.id='calendarView';calendarView.hidden=true;calendarView.innerHTML='<div class="calendar-heading"><div><span class="kicker">Shared project schedule</span><h2>Calendar</h2><p>Awarded jobs appear for both the contractor and subcontractor.</p></div><div class="calendar-month-controls"><button class="button button-outline" id="calendarPrev" type="button">&larr;</button><strong id="calendarMonth"></strong><button class="button button-outline" id="calendarNext" type="button">&rarr;</button></div></div><div class="calendar-layout"><article class="workspace-card calendar-board"><div class="calendar-weekdays"><span>Sun</span><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span></div><div class="calendar-grid" id="calendarGrid"></div></article><aside class="workspace-card upcoming-panel"><span class="kicker">Scheduled work</span><h3>Upcoming projects</h3><div id="upcomingJobs"></div></aside></div>';profileView.before(calendarView);
const scheduleDialog=document.createElement('dialog');scheduleDialog.className='modal modal-small schedule-modal';scheduleDialog.innerHTML='<button class="modal-close" type="button" data-close-schedule>&times;</button><div class="modal-heading"><span class="kicker" id="scheduleKicker">Award and schedule</span><h2 id="scheduleTitle">Schedule project</h2><p id="scheduleIntro">These dates will appear on both companies’ Trades calendars.</p></div><form id="scheduleForm"><input name="jobId" type="hidden"><input name="bidId" type="hidden"><div class="form-row"><label><span>Start date</span><input name="startDate" type="date" required></label><label><span>End date</span><input name="endDate" type="date" required></label></div><label><span>Schedule notes</span><textarea name="calendarNotes" rows="3" placeholder="Arrival time, site contact, milestones, or access notes"></textarea></label><button class="button button-orange button-full" type="submit">Confirm award and schedule</button></form>';document.body.appendChild(scheduleDialog);
let calendarEvents=[],calendarCursor=new Date();calendarCursor.setDate(1);
function dateKey(value){return String(value||'').slice(0,10)}function humanDate(value){return new Date(`${dateKey(value)}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}function eventActions(event){return `<div class="calendar-actions"><a class="text-link" href="${escapeHtml(event.googleUrl)}" target="_blank" rel="noopener">Google</a><a class="text-link" href="${escapeHtml(event.outlookUrl)}" target="_blank" rel="noopener">Outlook</a><a class="text-link" href="${escapeHtml(event.icsPath)}">Download</a><button class="text-link" type="button" data-edit-schedule="${event.id}">Edit</button></div>`}
function renderCalendar(){const year=calendarCursor.getFullYear(),month=calendarCursor.getMonth(),first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),leading=first.getDay();document.getElementById('calendarMonth').textContent=first.toLocaleDateString(undefined,{month:'long',year:'numeric'});let cells='';for(let i=0;i<leading;i++)cells+='<div class="calendar-day empty"></div>';for(let day=1;day<=days;day++){const key=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,events=calendarEvents.filter(event=>dateKey(event.startDate)<=key&&dateKey(event.endDate)>=key);cells+=`<div class="calendar-day ${events.length?'has-event':''}"><span>${day}</span>${events.slice(0,2).map(event=>`<button type="button" data-calendar-event="${event.id}">${escapeHtml(event.title)}</button>`).join('')}${events.length>2?`<small>+${events.length-2} more</small>`:''}</div>`}document.getElementById('calendarGrid').innerHTML=cells;const upcoming=[...calendarEvents].sort((a,b)=>dateKey(a.startDate).localeCompare(dateKey(b.startDate)));document.getElementById('upcomingJobs').innerHTML=upcoming.length?upcoming.map(event=>`<article class="upcoming-job" id="calendar-${event.id}"><span class="trade-pill">${escapeHtml(event.trade)}</span><h4>${escapeHtml(event.title)}</h4><p>${humanDate(event.startDate)} - ${humanDate(event.endDate)}<br>${escapeHtml(event.city)}, ${escapeHtml(event.state)}</p><small>With ${escapeHtml(event.partnerCompany.name)}</small>${event.calendarNotes?`<em>${escapeHtml(event.calendarNotes)}</em>`:''}${eventActions(event)}</article>`).join(''):'<div class="list-empty">Awarded jobs with confirmed dates will appear here.</div>';document.querySelectorAll('[data-calendar-event]').forEach(button=>button.onclick=()=>document.getElementById(`calendar-${button.dataset.calendarEvent}`)?.scrollIntoView({behavior:'smooth',block:'center'}));document.querySelectorAll('[data-edit-schedule]').forEach(button=>button.onclick=()=>openScheduleEdit(button.dataset.editSchedule))}
async function loadCalendar(){try{const result=await api('/api/calendar');calendarEvents=result.events;document.getElementById('calendarCount').textContent=calendarEvents.length||'';renderCalendar()}catch(error){showNotice(error.message,true)}}
function openAwardSchedule(jobId,bidId,companyName='selected subcontractor'){const job=dashboard.postedJobs.find(item=>item.id===jobId),form=document.getElementById('scheduleForm');form.reset();form.elements.jobId.value=jobId;form.elements.bidId.value=bidId;form.elements.startDate.value=dateKey(job?.startDate);form.elements.endDate.value=dateKey(job?.startDate);document.getElementById('scheduleKicker').textContent='Award and schedule';document.getElementById('scheduleTitle').textContent=job?.title||'Schedule project';document.getElementById('scheduleIntro').textContent=`Award this job to ${companyName} and add it to both companies’ calendars.`;form.querySelector('[type="submit"]').textContent='Confirm award and schedule';scheduleDialog.showModal()}
function openScheduleEdit(eventId){const event=calendarEvents.find(item=>item.id===eventId),form=document.getElementById('scheduleForm');form.reset();form.elements.jobId.value=event.id;form.elements.startDate.value=dateKey(event.startDate);form.elements.endDate.value=dateKey(event.endDate);form.elements.calendarNotes.value=event.calendarNotes||'';document.getElementById('scheduleKicker').textContent='Shared schedule';document.getElementById('scheduleTitle').textContent=event.title;document.getElementById('scheduleIntro').textContent='Updates are reflected on both companies’ Trades calendars. Re-add external calendar events after changing dates.';form.querySelector('[type="submit"]').textContent='Update shared schedule';scheduleDialog.showModal()}
window.openAwardSchedule=openAwardSchedule;document.querySelector('[data-close-schedule]').onclick=()=>scheduleDialog.close();document.getElementById('scheduleForm').addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget)),jobId=data.jobId,bidId=data.bidId;delete data.jobId;delete data.bidId;try{if(bidId)await api(`/api/jobs/${jobId}/award`,{method:'POST',body:JSON.stringify({...data,bidId})});else await api(`/api/calendar/jobs/${jobId}`,{method:'PUT',body:JSON.stringify(data)});scheduleDialog.close();await refresh();await loadCalendar();switchView('calendar');showNotice(bidId?'Bid awarded and project added to both calendars.':'Shared project schedule updated.')}catch(error){showNotice(error.message,true)}});calendarNav.addEventListener('click',()=>{switchView('calendar');loadCalendar()});document.getElementById('calendarPrev').onclick=()=>{calendarCursor.setMonth(calendarCursor.getMonth()-1);renderCalendar()};document.getElementById('calendarNext').onclick=()=>{calendarCursor.setMonth(calendarCursor.getMonth()+1);renderCalendar()};if(location.pathname==='/calendar'){switchView('calendar');loadCalendar()}else loadCalendar();
